/// Return the Line_Break class for a code point.
/// Handles default ranges for CJK (ID), currency (PR), etc.
pub fn lb(cp: u32) -> Lb {
    // Binary search
    let mut lo: usize = 0;
    let mut hi: usize = LB_RANGES.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (start, end, _) = LB_RANGES[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return LB_RANGES[mid].2;
        }
    }
    // Default ranges from LineBreak.txt header:
    // CJK blocks default to ID
    if (0x3400..=0x4DBF).contains(&cp)
        || (0x4E00..=0x9FFF).contains(&cp)
        || (0xF900..=0xFAFF).contains(&cp)
        || (0x20000..=0x2FFFD).contains(&cp)
        || (0x30000..=0x3FFFD).contains(&cp)
        || (0x1F000..=0x1F7FF).contains(&cp)
        || (0x1F900..=0x1FAFF).contains(&cp)
        || (0x1FC00..=0x1FFFD).contains(&cp)
    {
        return Lb::ID;
    }
    // Currency Symbols default to PR
    if (0x20A0..=0x20CF).contains(&cp) {
        return Lb::PR;
    }
    Lb::XX
}

