/// Return true if the code point has East_Asian_Width W or F.
pub fn is_east_asian_wide(cp: u32) -> bool {
    let mut lo: usize = 0;
    let mut hi: usize = EAW_WIDE_RANGES.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let (start, end) = EAW_WIDE_RANGES[mid];
        if cp < start {
            hi = mid;
        } else if cp > end {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

